import { test, expect } from '@playwright/test';

test.describe('Filtered Table View Printing', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-view');
  });

  test('should filter the table and print the results', async ({ page }) => {
    await page.getByLabel('Filter by name').fill('John Doe');
    await page.getByRole('button', { name: 'Apply Filter' }).click();

    const filteredRow = await page.getByText('John Doe');
    await expect(filteredRow).toBeVisible();
  });

  test('should print the filtered table', async ({ page }) => {
    await page.getByLabel('Filter by name').fill('Jane Smith');
    await page.getByRole('button', { name: 'Apply Filter' }).click();

    await page.getByRole('button', { name: 'Print' }).click();

    const printDialog = await page.getByText('Print Preview');
    await expect(printDialog).toBeVisible();
  });
});
